import math

# Parse values from output.txt
vals = {}
with open('crypto_primary_knowledge/output.txt','r') as f:
    for line in f:
        if '=' in line:
            k, v = line.split('=', 1)
            vals[k.strip()] = int(v.strip())

n = vals['n']
e = vals['e']
c = vals['c']

phi = n - 1

def invmod(a, m):
    # Extended Euclidean Algorithm
    a0, m0, x0, x1 = a, m, 0, 1
    if m == 1:
        return 0
    while a0 > 1:
        q = a0 // m0
        a0, m0 = m0, a0 % m0
        x0, x1 = x1 - q * x0, x0
    if x1 < 0:
        x1 += m
    return x1

try:
    d = pow(e, -1, phi)
except ValueError:
    if math.gcd(e, phi) != 1:
        raise SystemExit("e and phi(n) are not coprime.")
    d = invmod(e, phi)

m = pow(c, d, n)
m_len = (m.bit_length() + 7) // 8
pt = m.to_bytes(m_len, 'big')

try:
    print(pt.decode())
except UnicodeDecodeError:
    # Fallback: show repr if non-UTF8
    print(repr(pt))
